// Expense Guard — a multi-company expense-review agent. Reviews one expense submission
// (company_id + receipt + claimed amount + category) against that company's written
// policy and returns a structured decision: approve / flag_for_review / reject.
//
// Schema-output agent WITH tools: it emits the decision through `outputSchema`, and
// drives to that decision by calling search_policy (fetch the company policy) and
// validate_expense (sanity-check the submission). Eve binds `model` statically at build
// time — there is no runtime model override.
import { defineAgent } from "eve";
import { ExpenseDecisionSchema } from "./lib/expense.schema.js";

export default defineAgent({
  model: "anthropic/claude-opus-4-1-20250805",
  // Dated Anthropic ids aren't in the Gateway model catalog, so pin the window to skip
  // the lookup diagnostic.
  modelContextWindowTokens: 200_000,
  outputSchema: ExpenseDecisionSchema,
});
// HTTP channel: POST /eve/v1/review runs one structured review turn and returns the
// decision. Per-request context flows body -> channel state -> metadata(state) ->
// instructions resolver (ctx.channel.metadata). A bare body falls back to the fixture.
import { z } from "zod";
import { defineChannel, POST, type Session, type SendPayload } from "eve/channels";
import { ExpenseDecisionSchema } from "../lib/expense.schema.js";
import { buildRequestView, type tRequestView } from "../lib/request-context.js";

type tJsonOutputSchema = NonNullable<SendPayload["outputSchema"]>;

// eve expects a run-scoped JSON schema (not a Zod object) on the send payload.
function toJsonSchema(schema: z.ZodType): tJsonOutputSchema {
  const { $schema, ...rest } = z.toJSONSchema(schema) as Record<string, unknown>;
  void $schema;
  return rest as tJsonOutputSchema;
}

type tStreamEvent = {
  type: string;
  data?: { result?: unknown; message?: string; code?: string };
};

// Drain the turn's event stream once, capturing the structured result / terminal failure.
async function drainDecision(session: Session): Promise<{ result: unknown; failure: string | null }> {
  const stream = await session.getEventStream();
  const reader = stream.getReader();
  let result: unknown;
  let failure: string | null = null;
  try {
    for (;;) {
      const { value, done } = await reader.read();
      if (done) break;
      const event = value as tStreamEvent;
      if (event.type === "result.completed") result = event.data?.result;
      if (event.type === "turn.completed") break;
      if (event.type === "turn.failed") {
        failure = `${event.data?.code ?? "unknown"} ${event.data?.message ?? ""}`.trim();
        break;
      }
    }
  } finally {
    reader.releaseLock();
  }
  return { result, failure };
}

const outputSchema = toJsonSchema(ExpenseDecisionSchema);

export default defineChannel<tRequestView | undefined, { state: tRequestView | undefined }>({
  state: { request: null, contextProvided: false },
  context: (state) => ({ state }),
  metadata: (state) => ({
    request: state?.request ?? null,
    contextProvided: state?.contextProvided ?? false,
  }),
  routes: [
    POST("/eve/v1/review", async (request, { send }) => {
      let body: unknown;
      try {
        body = await request.json();
      } catch {
        return Response.json({ ok: false, error: "Invalid JSON body." }, { status: 400 });
      }

      const view = buildRequestView(body);
      const session = await send(
        { message: "Review the expense submission and return your decision.", outputSchema },
        { auth: null, continuationToken: `eve:${crypto.randomUUID()}`, state: view },
      );

      const { result, failure } = await drainDecision(session);
      if (failure) {
        return Response.json({ ok: false, error: `turn failed: ${failure}` }, { status: 502 });
      }

      const parsed = ExpenseDecisionSchema.safeParse(result);
      if (!parsed.success) {
        return Response.json(
          { ok: false, error: "Agent output did not match the decision schema." },
          { status: 502 },
        );
      }

      return Response.json({ ok: true, data: parsed.data }, { status: 200 });
    }),
  ],
});
// Per-request context for a review: the expense submission plus a few trace-identity
// fields. In production a channel maps the POST body onto the session; in dev / eval it
// loads a representative submission from a fixture (override with POC_REQUEST_FILE).
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { defineState } from "eve/context";

export type tExpenseLineItem = {
  label: string;
  amount: number;
};

export type tExpenseSubmission = {
  company_id: string;
  category: string;
  claimed_amount: number;
  currency?: string;
  receipt: string;
  line_items?: tExpenseLineItem[];
  workspace_id?: string;
  chat_id?: string;
  label?: string;
};

// The per-session projection carried by channel state -> metadata(state). `contextProvided`
// tells "bare request, use fixture" apart from "a body was sent but did not survive the
// projection".
export type tRequestView = {
  request: tExpenseSubmission | null;
  contextProvided: boolean;
};

const FIXTURE_PATH = process.env.POC_REQUEST_FILE ?? join(process.cwd(), "fixtures", "request.json");

export function loadExpenseFixture(): tExpenseSubmission {
  return JSON.parse(readFileSync(FIXTURE_PATH, "utf8")) as tExpenseSubmission;
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === "object" && v !== null && !Array.isArray(v);
}

// WRITE side — the channel builds the state to seed from the parsed body. A bare body
// (missing/empty/non-object) -> fixture path (contextProvided:false). A non-empty object
// body IS the submission (contextProvided:true).
export function buildRequestView(body: unknown): tRequestView {
  if (isPlainObject(body) && Object.keys(body).length > 0) {
    return { request: body as tExpenseSubmission, contextProvided: true };
  }
  return { request: null, contextProvided: false };
}

// READ side — loud fallback: a body was provided but did not reach the resolver via the
// metadata projection -> throw (fail the turn). Silently rendering the fixture would
// review another company's submission. Bare / eval requests -> fixture.
export function resolveExpenseSubmission(
  view: { request?: unknown; contextProvided?: unknown } | undefined,
): tExpenseSubmission {
  if (view?.contextProvided === true) {
    if (isPlainObject(view.request)) return view.request as tExpenseSubmission;
    throw new Error(
      "Per-request expense context was provided but did not reach the resolver via channel " +
        "metadata/state. Refusing to fall back to the fixture — that would review another " +
        "company's submission.",
    );
  }
  return loadExpenseFixture();
}

// The authoritative submission for this turn, seeded by the instructions resolver so
// tools can read the real fields instead of relying on model-provided arguments.
export const submissionState = defineState<tExpenseSubmission | null>(
  "expense-guard.submission",
  () => null,
);

