        type: 'object',
        properties: {
          file: { type: 'string', description: 'repo-relative path, with :line if known' },
          symptom: { type: 'string', description: 'what goes wrong, concretely — the observable defect, not the code smell' },
          repro_idea: { type: 'string', description: 'a specific test or sequence that would expose it, including expected vs actual' },
          severity: { type: 'string', enum: ['high', 'medium', 'low'] },
          why_real: { type: 'string', description: 'the evidence from the code that this is a genuine defect' },
        },
        required: ['file', 'symptom', 'repro_idea', 'severity', 'why_real'],
        additionalProperties: false,
      },
    },
  },
  required: ['findings'],
  additionalProperties: false,
}

const VERDICT_SCHEMA = {
  type: 'object',
  properties: {
    refuted: { type: 'boolean', description: 'true if this is NOT a real bug (framework idiom, intended behavior, or misreading)' },
    confidence: { type: 'string', enum: ['high', 'medium', 'low'] },
    reasoning: { type: 'string', description: 'what you checked and what you concluded' },
    correction: { type: 'string', description: 'if the finding is real but mis-stated (wrong file, overstated severity, wrong mechanism), state the corrected version. Empty string if no correction needed.' },
  },
  required: ['refuted', 'confidence', 'reasoning', 'correction'],
  additionalProperties: false,
}

const AXES = [
  {
    key: 'correctness',
    prompt: `${GROUND_RULES}

YOUR AXIS: CORRECTNESS — logic that produces a wrong decision.
Look hard at: agent/tools/validate_expense.ts (what does it actually verify vs what the
prompt claims it verifies?); agent/lib/policy-store.ts selectRules() topic-matching and
its fallback behavior; agent/lib/request-context.ts buildRequestView/resolveExpenseSubmission
edge cases (what bodies slip through?); the drainDecision loop in agent/channels/eve.ts
(what event sequences leave \`result\` undefined or mis-set?); whether the decision rubric
in agent/lib/build-instructions.ts can be satisfied in contradictory ways; whether
line_items / claimed_amount / currency are ever reconciled; ExpenseDecisionSchema fields
the model can fill in with something inconsistent with the actual submission.`,
  },
  {
    key: 'tenant-security',
    prompt: `${GROUND_RULES}

YOUR AXIS: TENANT SECURITY — anything letting one company's review see, use, or leak
another company's data, or letting untrusted input steer the tenancy decision.
Look hard at: the fact that submissionState is seeded but apparently never READ — trace
every consumer and confirm; both tools taking company_id from model-supplied arguments;
the receipt field as an untrusted prompt-injection channel (it is raw OCR text) and what
the model could be talked into; POLICIES[companyId] ?? POLICIES.acme fallback semantics;
whether workspace_id/chat_id are validated against company_id at all; whether anything is
shared across requests in module scope besides the known policy cache (search the whole
agent/ tree for module-level mutable state); what the channel's continuationToken /
session model does or does not isolate; whether error messages leak other tenants' data.`,
  },
  {
    key: 'cost',
    prompt: `${GROUND_RULES}

YOUR AXIS: COST — tokens and model spend treated as a design constraint.
Look hard at: agent/agent.ts model pin and modelContextWindowTokens (note: the model was
just repointed to anthropic/claude-haiku-4.5 after the shipped opus-4-1 pin 404'd — assess
whether haiku is the right call and whether the stale comment above it now misleads);
how many model steps a single review costs and whether any are avoidable; the size and
shape of the tool definitions sent every request; whether search_policy returns more text
than needed (selectRules fallback returning ALL rules); the agent-level outputSchema plus
the channel re-attaching a per-request outputSchema — is that duplicated in the payload?;
evals/evals.config.ts judge model and concurrency; anything that would multiply cost under
production load. Exclude the known prompt-ordering cache issue.`,
  },
  {
    key: 'maintainability',
    prompt: `${GROUND_RULES}

YOUR AXIS: MAINTAINABILITY — code that will cause the next bug.
Look hard at: agent/tools/validate_expense.ts doIt() (dead locals, unused computed values,
commented-out logic, meaningless names, values computed then dropped by the caller);
string-concatenation prompt building in agent/lib/build-instructions.ts and the dead
oldRender comment; hand-rolled index loops in agent/lib/policy-store.ts and
agent/lib/policies.ts push-based construction; duplicated fixtures (valid.json vs
request.json are byte-identical — what does that imply?); the type-alias naming convention
(tFoo) and whether it is applied consistently; error handling that swallows detail;
evals/ coverage gaps as a maintainability problem (fixtures that nothing exercises);
whether tsconfig strictness is actually buying anything given the escape hatches used
(\`as\` casts across trust boundaries). Prioritize things that would let a REAL bug through,
not pure style.`,
  },
]

phase('Find')
log('Auditing 4 axes read-only; each finding then gets an adversarial refutation pass.')

const results = await pipeline(
  AXES,
  (axis) => agent(axis.prompt, {
    label: `find:${axis.key}`,
    phase: 'Find',
    schema: FINDING_SCHEMA,
  }),
  (found, axis) => {
    if (!found || !found.findings || found.findings.length === 0) {
      log(`${axis.key}: no findings returned`)
      return []
    }
    log(`${axis.key}: ${found.findings.length} finding(s) -> refuting`)
    return parallel(found.findings.map((f) => () =>
      agent(`${GROUND_RULES}

YOUR JOB: REFUTE the finding below. You are a skeptic, not a confirmer. Another agent
claims this is a bug on the ${axis.key} axis. Your default posture is that it is NOT a
real defect — that it is an Eve framework idiom, intended behavior, a misreading of the
code, already-handled elsewhere, or unreachable in practice. Only concede it is real if
the code genuinely forces the bad outcome.

Read the actual file and the surrounding code before concluding. Check node_modules/eve
if the claim depends on framework behavior. If the finding is real but mis-stated — wrong
mechanism, wrong file, overstated severity — say so in \`correction\` rather than refuting
outright.

CLAIMED FINDING
  axis:     ${axis.key}
  file:     ${f.file}
  severity: ${f.severity}
  symptom:  ${f.symptom}
  repro:    ${f.repro_idea}
  claimed evidence: ${f.why_real}

Set refuted=true if this is not a real bug. Set refuted=false only if you verified the
code forces the defect. When genuinely uncertain, lean refuted=true and say why in reasoning.`,
      {
        label: `refute:${axis.key}:${(f.file || '').split('/').pop()}`,
        phase: 'Refute',
        schema: VERDICT_SCHEMA,
      },
    ).then((v) => ({ axis: axis.key, ...f, verdict: v }))))
  },
)

const all = results.flat().filter(Boolean)
const survived = all.filter((x) => x.verdict && x.verdict.refuted === false)
const killed = all.filter((x) => x.verdict && x.verdict.refuted === true)
const unjudged = all.filter((x) => !x.verdict)

log(`audit complete: ${all.length} raised, ${survived.length} survived refutation, ${killed.length} refuted`)

return {
  summary: {
    raised: all.length,
    survived: survived.length,
    refuted: killed.length,
    unjudged: unjudged.length,
  },
  survived,
  refuted: killed.map((x) => ({
    axis: x.axis,
    file: x.file,
    symptom: x.symptom,
    why_refuted: x.verdict.reasoning,
    confidence: x.verdict.confidence,
  })),
}

