1	// HTTP channel: POST /eve/v1/review runs one structured review turn and returns the
2	// decision. Per-request context flows body -> channel state -> metadata(state) ->
3	// instructions resolver (ctx.channel.metadata). A bare body falls back to the fixture.
4	import { z } from "zod";
5	import { defineChannel, POST, type Session, type SendPayload } from "eve/channels";
6	import { ExpenseDecisionSchema } from "../lib/expense.schema.js";
7	import {
8	  loadExpenseFixture,
9	  parseRequestBody,
10	  type tRequestView,
11	} from "../lib/request-context.js";
12	import { hasCompanyPolicy } from "../lib/policy-store.js";
13	import { finalizeDecision } from "../lib/finalize-decision.js";
14	import { appendDecisionRecord } from "../lib/decision-log.js";
15	import { AGENT_MODEL } from "../lib/model.js";
16	
17	type tJsonOutputSchema = NonNullable<SendPayload["outputSchema"]>;
18	
19	// eve expects a run-scoped JSON schema (not a Zod object) on the send payload.
20	function toJsonSchema(schema: z.ZodType): tJsonOutputSchema {
21	  const { $schema, ...rest } = z.toJSONSchema(schema) as Record<string, unknown>;
22	  void $schema;
23	  return rest as tJsonOutputSchema;
24	}
25	
26	type tStreamEvent = {
27	  type: string;
28	  data?: {
29	    result?: unknown;
30	    message?: string;
31	    code?: string;
32	    usage?: {
33	      readonly inputTokens?: number;
34	      readonly outputTokens?: number;
35	      readonly cacheReadTokens?: number;
36	      readonly cacheWriteTokens?: number;
37	    };
38	  };
39	};
40	
41	type tDrainedTurn = {
42	  result: unknown;
43	  failure: string | null;
44	  inputTokens: number;
45	  outputTokens: number;
46	  cacheReadTokens: number;
47	  cacheWriteTokens: number;
48	};
49	
50	// Drain the turn's event stream once, capturing the structured result / terminal failure,
51	// and summing per-step token usage along the way. A review is several model steps, so the
52	// cost of a decision is the sum over `step.completed` — the same fields
53	// agent/hooks/usage-log.ts prints per step, totalled here because the audit record needs
54	// one number per decision rather than one per step.
55	async function drainDecision(session: Session): Promise<tDrainedTurn> {
56	  const stream = await session.getEventStream();
57	  const reader = stream.getReader();
58	  let result: unknown;
59	  let failure: string | null = null;
60	  let inputTokens = 0;
61	  let outputTokens = 0;
62	  let cacheReadTokens = 0;
63	  let cacheWriteTokens = 0;
64	  try {
65	    for (;;) {
66	      const { value, done } = await reader.read();
67	      if (done) break;
68	      const event = value as tStreamEvent;
69	      if (event.type === "step.completed") {
70	        const usage = event.data?.usage;
71	        inputTokens = inputTokens + (usage?.inputTokens ?? 0);
72	        outputTokens = outputTokens + (usage?.outputTokens ?? 0);
73	        cacheReadTokens = cacheReadTokens + (usage?.cacheReadTokens ?? 0);
74	        cacheWriteTokens = cacheWriteTokens + (usage?.cacheWriteTokens ?? 0);
75	      }
76	      if (event.type === "result.completed") result = event.data?.result;
77	      if (event.type === "turn.completed") break;
78	      if (event.type === "turn.failed") {
79	        failure = `${event.data?.code ?? "unknown"} ${event.data?.message ?? ""}`.trim();
80	        break;
81	      }
82	    }
83	  } finally {
84	    reader.releaseLock();
85	  }
86	  return { result, failure, inputTokens, outputTokens, cacheReadTokens, cacheWriteTokens };
87	}
88	
89	const outputSchema = toJsonSchema(ExpenseDecisionSchema);
90	
91	export default defineChannel<tRequestView | undefined, { state: tRequestView | undefined }>({
92	  state: { request: null, contextProvided: false },
93	  context: (state) => ({ state }),
94	  metadata: (state) => ({
95	    request: state?.request ?? null,
96	    contextProvided: state?.contextProvided ?? false,
97	  }),
98	  routes: [
99	    POST("/eve/v1/review", async (request, { send }) => {
100	      let body: unknown;
101	      try {
102	        body = await request.json();
103	      } catch {
104	        return Response.json({ ok: false, error: "Invalid JSON body." }, { status: 400 });
105	      }
106	
107	      // Ingress guardrail — runs before the turn is opened, so a malformed submission or
108	      // an unknown tenant costs zero model tokens. A bare body is not rejected here: that
109	      // is the documented dev/eval path to the fixture.
110	      const parsedBody = parseRequestBody(body);
111	      if (!parsedBody.ok) {
112	        return Response.json(
113	          { ok: false, error: "Invalid expense submission.", problems: parsedBody.problems },
114	          { status: 400 },
115	        );
116	      }
117	
118	      const view = parsedBody.view;
119	
120	      // Resolve the tenant ONCE, here, and use that single value for both the ingress gate
121	      // and the post-turn citation check. Deriving it twice made the isolation invariant
122	      // "the two derivations agree" rather than "there is one".
123	      const submission = view.request ?? loadExpenseFixture();
124	
125	      if (!hasCompanyPolicy(submission.company_id)) {
126	        // A caller error, not an agent failure — 400, and cheap. Before this check an
127	        // unknown company_id was silently adjudicated against Acme's rules; after the
128	        // policy-store fix it failed, but only after paying for a whole review.
