1	// Builds Expense Guard's system instructions for a single review.
2	import { type tExpenseSubmission } from "./request-context.js";
3	
4	function header() {
5	  let out = "";
6	  out = out + "You are Expense Guard, an automated expense-review agent for a multi-company expense\n";
7	  out = out + "platform. Each submission gives you a company_id, a receipt (raw OCR text), a claimed\n";
8	  out = out + "amount, and a category. Return exactly one decision: approve, flag_for_review, or reject.\n";
9	  return out;
10	}
11	
12	function steps() {
13	  let x = "";
14	  x = x + "\n";
15	  x = x + "How to review a submission:\n";
16	  x = x + "1. Call search_policy to retrieve the written expense policy for the company under\n";
17	  x = x + "   review. It takes no company_id — the platform decides whose policy you get, and you\n";
18	  x = x + "   cannot look up another company. Never rely on policy you remember from elsewhere:\n";
19	  x = x + "   each company sets its own limits, and different companies reuse the same rule ids.\n";
20	  x = x + "2. Compare the claimed amount and category against the rules you retrieved.\n";
21	  x = x + "3. Call verify_totals. It reconciles the receipt's line items against the claimed\n";
22	  x = x + "   amount in code and returns the arithmetic as a fact — do not add the receipt up\n";
23	  x = x + "   yourself. A \"mismatch\" status means the claim is not supported by the itemised\n";
24	  x = x + "   receipt: treat that as a reason to reject or flag, whatever the policy limits say,\n";
25	  x = x + "   and quote the figures it returns in your reason. A \"no_line_items\" status means the\n";
26	  x = x + "   total could not be verified — judge the receipt text on its own merits and say so.\n";
27	  x = x + "4. Check that the receipt is legible before you decide.\n";
28	  return x;
29	}
30	
31	function rubric() {
32	  let r = "";
33	  r = r + "\n";
34	  r = r + "Decision rubric:\n";
35	  r = r + "- approve: the expense clearly falls within a policy rule and nothing looks off.\n";
36	  r = r + "- flag_for_review: the expense is over a limit that allows manager/approver sign-off, or\n";
37	  r = r + "  something is ambiguous and a human should take a look.\n";
38	  r = r + "- reject: the expense violates a hard rule (for example a non-reimbursable category).\n";
39	  r = r + "\n";
40	  r = r + "Put the id of the rule that drives your decision in cited_rule_id, exactly as\n";
41	  r = r + "search_policy returned it (for example MEAL-01). It must be a rule from THIS\n";
42	  r = r + "submission's company — never one you remember from another company, and never an id\n";
43	  r = r + "you invent. If no retrieved rule fits, pick the closest one that genuinely applies and\n";
44	  r = r + "explain the mismatch in reason. Put that rule's text in cited_rule, quoted as closely\n";
45	  r = r + "as you can rather than paraphrased.\n";
46	  r = r + "In your reason, quote the specific receipt details that justify the decision so a\n";
47	  r = r + "reviewer can see the evidence you used, along with any limit you derived (for example\n";
48	  r = r + "a per-attendee cap multiplied by the number of attendees).";
49	  return r;
50	}
51	
52	function renderSubmission(submission: tExpenseSubmission, now: Date): string {
53	  const cur = submission.currency ?? "USD";
54	  const li = submission.line_items ?? [];
55	  const payload = {
56	    company_id: submission.company_id,
57	    category: submission.category,
58	    claimed_amount: submission.claimed_amount,
59	    currency: cur,
60	    receipt: submission.receipt,
61	    line_items: li,
62	  };
63	  let block = "";
64	  block = block + "Current date: " + now.toISOString() + "\n";
65	  block = block + "Submission under review:" + "\n";
66	  block = block + JSON.stringify(payload, null, 2);
67	  return block;
68	}
69	
70	// Static first, volatile last.
71	//
72	// Prompt caching keys on a shared prefix: everything from the first byte that differs
73	// between two requests is uncacheable. This prompt used to open with the submission JSON
74	// and an ISO timestamp — the two things that change on every single request — so the
75	// identical instruction block that followed could never be reused, and every review re-billed
76	// it in full.
77	//
78	// Ordering the stable instructions first makes that block a byte-identical prefix across all
79	// requests, which is the precondition for caching. It does NOT by itself turn caching on:
80	// that needs an explicit cache breakpoint from the provider/framework, and the per-step
81	// figures from agent/hooks/usage-log.ts are the only honest way to confirm any of it landed.
82	// This change makes the prompt cache-READY; it does not claim a measured saving.
83	//
84	// Structural invariant, asserted in scripts/prompt-structure.test.ts: two prompts that differ
85	// only in their submission must share the whole instruction block as a common prefix.
86	export function buildSystemPrompt(submission: tExpenseSubmission, now: Date): string {
87	  let prompt = "";
88	  prompt = prompt + header();
89	  prompt = prompt + steps();
90	  prompt = prompt + rubric();
91	  prompt = prompt + "\n\n";
92	  prompt = prompt + renderSubmission(submission, now);
93	  return prompt;
94	}

