1	// Fail-closed guardrail on a decision's citation.
2	//
3	// `cited_rule_id` names the rule the decision claims to be applying, and `modelFreeText` is
4	// the model's own prose about it (today: the `reason` field). Nothing upstream constrains
5	// either to the rules search_policy actually returned, so a decision can cite a rule
6	// belonging to another tenant (what the policy-store cache bug produced) or one that exists
7	// nowhere at all. This runs server-side against the company_id from the request — never a
8	// model-supplied value.
9	//
10	// It answers one question: does the cited rule belong to THIS company's policy? It does not
11	// judge whether the rule justifies the decision.
12	import type { tPolicyRule } from "./policies.js";
13	import { findRule, getCompanyPolicy, otherPolicies, ownersOfRuleId } from "./policy-store.js";
14	
15	export type tCitationFailureCode =
16	  | "unresolvable_policy"
17	  | "no_rule_id"
18	  | "foreign_or_unknown_rule"
19	  | "foreign_rule_text";
20	
21	export type tCitationCheck =
22	  | { ok: true; rule: tPolicyRule }
23	  | {
24	      ok: false;
25	      code: tCitationFailureCode;
26	      // Safe to return over HTTP. Deliberately does not reveal which other company owns a
27	      // rule, or any other tenant's rule text — that would turn the guardrail itself into
28	      // the disclosure channel it exists to prevent.
29	      publicMessage: string;
30	      // Server-side logging only. May name other tenants.
31	      logDetail: string;
32	    };
33	
34	// Rule ids in this policy set look like MEAL-01, TRVL-01, GEN-01, CASH-01, SW-01.
35	// The scanning pattern is uppercase-only on purpose: it runs over free-form prose, where a
36	// case-insensitive match would fire on ordinary hyphenated tokens.
37	const RULE_ID_PATTERN = /\b[A-Z]{2,8}-\d{1,3}\b/g;
38	// The dedicated cited_rule_id field is allowed to be sloppy — "[meal-01]" is still a
39	// recognisable id — but it must at least have the shape of one.
40	const RULE_ID_SHAPE = /\b[A-Za-z]{2,8}-\d{1,3}\b/;
41	
42	// Length of the verbatim word run used to detect copied foreign rule text. Long enough that
43	// ordinary paraphrase of a company's own rule will not trip it, short enough that quoting
44	// another company's rule will.
45	const SHINGLE_WORDS = 6;
46	
47	function normalize(text: string): string {
48	  return text
49	    .toLowerCase()
50	    .replace(/,/g, "")
51	    .replace(/[^a-z0-9$]+/g, " ")
52	    .trim();
53	}
54	
55	function shingles(text: string, size: number): string[] {
56	  const words = text.split(" ").filter(Boolean);
57	  const out: string[] = [];
58	  for (let i = 0; i + size <= words.length; i = i + 1) {
59	    out.push(words.slice(i, i + size).join(" "));
60	  }
61	  return out;
62	}
63	
64	type tForeignShingle = { company: string; ruleId: string; shingle: string };
65	
66	// POLICIES never mutates at runtime, so the cross-tenant index and each company's own
67	// normalized corpus are derived once at module load rather than rebuilt on every request.
68	// At three tenants that is microseconds either way — the reason to precompute is that the
69	// per-request path collapses from a four-deep nested loop to a flat scan, and the cost
70	// stops being O(tenants x rules x words) per review.
71	const FOREIGN_SHINGLES = new Map<string, tForeignShingle[]>();
72	const OWN_TEXT = new Map<string, string>();
73	
74	function foreignShinglesFor(companyId: string): tForeignShingle[] {
75	  const cached = FOREIGN_SHINGLES.get(companyId);
76	  if (cached) return cached;
77	  const built = otherPolicies(companyId).flatMap((policy) =>
78	    policy.rules.flatMap((rule) =>
