131	  // The decision names the rule by id. Resolving that id against this company's policy is
132	  // what makes the returned rule text authoritative rather than model prose.
133	  const normalizedId = (citedRuleId.match(RULE_ID_SHAPE)?.[0] ?? "").toUpperCase();
134	  if (!normalizedId) {
135	    return {
