154	  // not sufficient. Catch a decision that quotes another company's rule text verbatim under
155	  // a locally-valid id, which is exactly what the policy cache leak produced.
156	  //
157	  // Note this is now a signal, not a containment barrier: the caller replaces cited_rule
158	  // with canonical store text regardless, so foreign wording cannot reach a consumer. What
159	  // it still catches is the model having REASONED from the wrong tenant's policy, which is
160	  // worth rejecting rather than silently canonicalising.
161	  const citedWords = normalize(modelFreeText);
162	  const ownText = ownTextFor(companyId, ownPolicy.rules);
163	  for (const foreign of foreignShinglesFor(companyId)) {
164	    if (!citedWords.includes(foreign.shingle)) continue;
165	    if (ownText.includes(foreign.shingle)) continue; // wording this company shares — not a leak
166	    return {
167	      ok: false,
168	      code: "foreign_rule_text",
169	      publicMessage:
170	        "The decision quoted policy text that is not part of this company's policy.",
171	      logDetail:
172	        `the decision's prose quoted "${foreign.shingle}" from ${foreign.company}'s ` +
173	        `${foreign.ruleId}, ` +
174	        `which does not appear in "${companyId}"'s policy`,
175	    };
176	  }
