acmeRules.push({ id: "ALC-01", category: "alcohol", text: "Alcohol is not reimbursable under any circumstances (reject).", scope: "global" });
POLICIES.acme = { company_id: "acme", company_name: "Acme Robotics", rules: acmeRules };

